mapper.select:
SELECT id, item_code, item_name, item_type, unit_price, unit, calc_method, is_default, status, create_time, update_time FROM fee_item WHERE is_deleted = 0
AND item_code LIKE CONCAT('%', #{itemCode}, '%')
AND item_name LIKE CONCAT('%', #{itemName}, '%')
AND item_type = #{itemType}
AND status = #{status}
ORDER BY create_time DESC
